        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrect logic in the conditional statement that determined when to emit a frame for a function call. The original implementation emitted a frame for tail calls, which is not the correct behavior, as frames should only be emitted for non-tail calls. This led to improper handling of the call stack and potential runtime errors.

        Commit message:
        Bugfix: fix bug introduced in commit 4779b1b  

        Patch:

 static rsexp compile_call_cc (RState* state, rsexp expr, rsexp next)
 {
     rsexp code;

     if (!validate_call_cc (state, expr))
         return R_FAILURE;

     r_gc_scope_open (state);

     ensure_or_goto (code = emit_apply (state), exit);
     ensure_or_goto (code = compile (state, r_cadr (expr), code), exit);
     ensure_or_goto (code = emit_arg (state, code), exit);
     ensure_or_goto (code = emit_capture_cc (state, code), exit);

-    if (tail_p (state, next))
-        ensure_or_goto (code = emit_frame (state, next, code), exit);
+    if (!tail_p (state, next))
+        code = emit_frame (state, next, code);

 exit:
     r_gc_scope_close_and_protect (state, code);

     return code;
 }



